(function(){
  const BERRY_ROWS = 7;
  let berries = [];
  for(let row=0; row<BERRY_ROWS; row++){
    let rowWidth = BERRY_ROWS-row;
    let y = row*15;
    for(let i=0;i<rowWidth;i++){
      let x = (i-(rowWidth-1)/2)*15 + (row%2===0?0:4);
      berries.push({ox:x, oy:y, r: 8+Math.random()*3, phase: Math.random()*Math.PI*2, cmix: Math.random()});
    }
  }

  let leaves = [];
  const LEAF_COUNT = 10;
  for(let i=0;i<LEAF_COUNT;i++){
    let side = Math.random()<0.5?0:1;
    leaves.push({
      xr: side===0 ? Math.random()*0.26 : 0.74+Math.random()*0.26,
      y: Math.random()*-1.2,
      size: 10+Math.random()*9,
      speed: 0.08+Math.random()*0.1,
      swing: 0.3+Math.random()*0.6,
      swingSpeed: 0.3+Math.random()*0.5,
      rot: Math.random()*Math.PI*2,
      rotSpeed: (Math.random()-0.5)*0.02,
      hue: Math.random(),
      phase: Math.random()*Math.PI*2
    });
  }

  let particles = [];
  const P_COUNT = 36;
  for(let i=0;i<P_COUNT;i++){
    particles.push({
      xr: 0.04+Math.random()*0.34,
      y: Math.random()*1.0,
      r: 1+Math.random()*2,
      speed: 0.1+Math.random()*0.15,
      phase: Math.random()*Math.PI*2,
      amp: 10+Math.random()*20
    });
  }

  function hexToRgb(hex){
    let h = hex.replace('#','');
    let num = parseInt(h,16);
    return [ (num>>16)&255, (num>>8)&255, num&255 ];
  }
  const c0 = hexToRgb(PALETTE[0]);
  const c1 = hexToRgb(PALETTE[1]);
  const c2 = hexToRgb(PALETTE[2]);

  function mix(a,b,t){
    return [ a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t ];
  }
  function rgba(arr, a){
    return 'rgba('+Math.round(arr[0])+','+Math.round(arr[1])+','+Math.round(arr[2])+','+a+')';
  }

  function drawLeafShape(size, color, alpha){
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.moveTo(0,-size);
    ctx.bezierCurveTo(size*0.7,-size*0.5, size*0.6,size*0.5, 0,size);
    ctx.bezierCurveTo(-size*0.6,size*0.5, -size*0.7,-size*0.5, 0,-size);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.fill();
    ctx.strokeStyle = rgba(c2,0.45);
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0,-size);
    ctx.lineTo(0,size);
    ctx.stroke();
    ctx.restore();
  }

  let t0 = performance.now();

  function frame(now){
    let t = (now-t0)*0.001;
    let w = W(), h = H();
    ctx.clearRect(0,0,w,h);
    let scale = Math.min(w,h)/900;

    let anchorX = w*0.20;
    let anchorY = h*0.72;
    let angle = Math.sin(t*0.3)*0.05;
    let cosA = Math.cos(angle), sinA = Math.sin(angle);

    ctx.save();
    ctx.strokeStyle = rgba(c2,0.7);
    ctx.lineWidth = 3*scale;
    ctx.lineCap='round';
    ctx.beginPath();
    ctx.moveTo(anchorX, anchorY-90*scale);
    ctx.quadraticCurveTo(anchorX-20*scale, anchorY-60*scale, anchorX, anchorY-10*scale);
    ctx.stroke();
    ctx.restore();

    ctx.save();
    ctx.translate(anchorX-18*scale, anchorY-80*scale);
    ctx.rotate(-0.4+Math.sin(t*0.4)*0.05);
    ctx.scale(scale,scale);
    drawLeafShape(30, rgba(mix(c1,c2,0.3),1), 0.85);
    ctx.restore();

    for(let b of berries){
      let rx = b.ox*cosA - b.oy*sinA;
      let ry = b.ox*sinA + b.oy*cosA;
      let bx = anchorX + rx*scale;
      let by = anchorY + ry*scale;
      let glow = 0.75 + 0.25*Math.sin(t*1.4 + b.phase);
      let col = mix(c0, c1, b.cmix*0.7);
      let r = b.r*scale;
      let grad = ctx.createRadialGradient(bx-r*0.3, by-r*0.35, r*0.1, bx, by, r);
      grad.addColorStop(0, rgba(mix(col,[255,255,255],0.22*glow), 0.95));
      grad.addColorStop(0.6, rgba(col, 0.9*glow));
      grad.addColorStop(1, rgba(mix(col,c2,0.4), 0.85));
      ctx.save();
      ctx.shadowColor = rgba(c1, 0.5);
      ctx.shadowBlur = 12*scale*glow;
      ctx.beginPath();
      ctx.arc(bx,by,r,0,Math.PI*2);
      ctx.fillStyle = grad;
      ctx.fill();
      ctx.restore();
    }

    for(let lf of leaves){
      lf.y += lf.speed*0.01;
      if(lf.y>1.2) lf.y = -0.2;
      lf.rot += lf.rotSpeed;
      let x = lf.xr*w + Math.sin(t*lf.swingSpeed + lf.phase)*lf.swing*30;
      let y = lf.y*h;
      ctx.save();
      ctx.translate(x,y);
      ctx.rotate(lf.rot + Math.sin(t*lf.swingSpeed+lf.phase)*0.3);
      let leafColor = rgba(mix(c1,c0, lf.hue), 0.8);
      drawLeafShape(lf.size, leafColor, 0.75);
      ctx.restore();
    }

    for(let p of particles){
      p.y -= p.speed*0.006;
      if(p.y<-0.05) p.y = 1.05;
      let x = p.xr*w + Math.sin(t*0.6+p.phase)*p.amp;
      let y = p.y*h;
      let a = 0.15+0.2*(0.5+0.5*Math.sin(t*1.1+p.phase));
      ctx.save();
      ctx.beginPath();
      ctx.arc(x,y,p.r*scale,0,Math.PI*2);
      ctx.fillStyle = rgba(c1, Math.max(0.05,a));
      ctx.shadowColor = rgba(c1,0.6);
      ctx.shadowBlur = 6*scale;
      ctx.fill();
      ctx.restore();
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
